window.COURSE={"pages":[{"key":"home","file":"Java.html","name":"Home","short":"Home","band":"","sections":[]},{"key":"l00","file":"lessons/00-foundations.html","name":"Lesson 00 · Foundations","short":"L00","band":"found","sections":[{"id":"f-platform","n":"F1","t":"The Java platform: JDK, JRE, JVM and bytecode"},{"id":"f-types","n":"F2","t":"Variables and types: primitives vs references"},{"id":"f-operators","n":"F3","t":"Operators, casting and arithmetic traps"},{"id":"f-control","n":"F4","t":"Control flow: if, switch and loops"},{"id":"f-methods","n":"F5","t":"Methods, overloading, scope and recursion"},{"id":"f-pass","n":"F6","t":"Pass-by-value: what really happens to arguments"},{"id":"f-io","n":"F7","t":"Packages, imports, input/output and the command line"},{"id":"f-review","n":"F8","t":"Foundations: interview questions and review"}]},{"key":"l01","file":"lessons/01-strings.html","name":"Lesson 01 · Strings","short":"L01","band":"","sections":[{"id":"what","n":"01","t":"What is a String?"},{"id":"create","n":"02","t":"Creating Strings"},{"id":"pool","n":"03","t":"Memory and the String Pool"},{"id":"immutable","n":"04","t":"Immutability"},{"id":"compare","n":"05","t":"Comparing Strings"},{"id":"chars","n":"06","t":"Characters, indexes and length"},{"id":"methods","n":"07","t":"Essential String methods"},{"id":"build","n":"08","t":"Building Strings: +, StringBuilder, StringBuffer"},{"id":"convert","n":"09","t":"Conversions"},{"id":"format","n":"10","t":"Formatting and text blocks"},{"id":"regex","n":"11","t":"Regex with Strings"},{"id":"unicode","n":"12","t":"Unicode, encoding and internals"},{"id":"mistakes","n":"13","t":"Common mistakes"},{"id":"qa","n":"14","t":"15 interview questions"},{"id":"practice","n":"15","t":"Practice"}]},{"key":"l02","file":"lessons/02-string-internals.html","name":"Lesson 02 · Deep dive","short":"L02","band":"deep","sections":[{"id":"d-memory","n":"D1","t":"The JVM memory map: where Strings live"},{"id":"d-anatomy","n":"D2","t":"Anatomy of a String object"},{"id":"d-scp","n":"D3","t":"The String Constant Pool (SCP) in depth"},{"id":"d-new","n":"D4","t":"What new String(\"x\") really does"},{"id":"d-equals","n":"D5","t":"== vs equals() vs hashCode() vs compareTo()"},{"id":"d-immutable","n":"D6","t":"Immutability: how it is built"},{"id":"d-builder","n":"D7","t":"StringBuilder and StringBuffer internals"},{"id":"d-concat","n":"D8","t":"How + concatenation works"},{"id":"d-methods","n":"D9","t":"Complete method reference"},{"id":"d-null","n":"D10","t":"null, CharSequence, and Strings elsewhere"},{"id":"d-tricky","n":"D11","t":"Tricky outputs"},{"id":"d-qa","n":"D12","t":"25 more interview questions"},{"id":"d-map","n":"D13","t":"Concept map"}]},{"key":"l03","file":"lessons/03-string-problems.html","name":"Lesson 03 · Problems","short":"L03","band":"probs","sections":[{"id":"s-approach","n":"S1","t":"How to approach any String problem"},{"id":"s-patterns","n":"S2","t":"The 7 patterns behind String problems"},{"id":"s-reverse","n":"S3","t":"Reversal: 5 ways, and reversing words"},{"id":"s-palin","n":"S4","t":"Palindromes"},{"id":"s-freq","n":"S5","t":"Counting and frequency"},{"id":"s-window","n":"S6","t":"Sliding window"},{"id":"s-stack","n":"S7","t":"Stacks and parsing"},{"id":"s-classic","n":"S8","t":"More classic problems"},{"id":"s-streams","n":"S9","t":"Strings with streams and Comparators"},{"id":"s-regex","n":"S10","t":"Regex, beyond the basics"},{"id":"s-qa","n":"S11","t":"15 more interview questions"},{"id":"s-practice","n":"S12","t":"Practice and pattern map"}]},{"key":"l04","file":"lessons/04-arrays.html","name":"Lesson 04 · Arrays","short":"L04","band":"arrays","sections":[{"id":"a-what","n":"A1","t":"What is an array?"},{"id":"a-create","n":"A2","t":"Declaring, creating and initialising"},{"id":"a-memory","n":"A3","t":"Memory: where arrays live"},{"id":"a-multi","n":"A4","t":"2D, jagged and multi-dimensional arrays"},{"id":"a-copy","n":"A5","t":"Copying: aliasing, shallow and deep"},{"id":"a-util","n":"A6","t":"The java.util.Arrays class"},{"id":"a-sort","n":"A7","t":"Sorting and searching"},{"id":"a-methods","n":"A8","t":"Arrays and methods"},{"id":"a-convert","n":"A9","t":"Arrays vs ArrayList, and conversions"},{"id":"a-internals","n":"A10","t":"Internals and advanced rules"},{"id":"a-patterns","n":"A11","t":"Core array patterns"},{"id":"a-mistakes","n":"A12","t":"Common mistakes"},{"id":"a-qa","n":"A13","t":"20 interview questions on arrays"},{"id":"a-practice","n":"A14","t":"Practice and concept map"}]},{"key":"l05","file":"lessons/05-oop.html","name":"Lesson 05 · OOP","short":"L05","band":"oop","sections":[{"id":"o-class","n":"P1","t":"Classes and objects: the blueprint and the thing"},{"id":"o-ctor","n":"P2","t":"Constructors and initialisation order"},{"id":"o-encap","n":"P3","t":"Encapsulation, access modifiers and immutable classes"},{"id":"o-static","n":"P4","t":"static members and nested classes"},{"id":"o-inherit","n":"P5","t":"Inheritance, super, and composition over inheritance"},{"id":"o-poly","n":"P6","t":"Polymorphism: overloading vs overriding"},{"id":"o-abstract","n":"P7","t":"Abstraction: abstract classes vs interfaces"},{"id":"o-object","n":"P8","t":"The Object class: equals, hashCode and toString"},{"id":"o-modern","n":"P9","t":"Modern OOP: records, enums and sealed types"},{"id":"o-review","n":"P10","t":"OOP: interview questions and review"}]},{"key":"l06","file":"lessons/06-bubble-sort.html","name":"Lesson 06 · Sorting","short":"L06","band":"bsort","sections":[{"id":"bs-explorer","n":"B0","t":"Sorting explorer: every interview sort"},{"id":"cx-complexity","n":"O(n)","t":"Time and space complexity: from scratch to advanced"},{"id":"bs-what","n":"B1","t":"What sorting is, and the idea behind bubble sort"},{"id":"bs-dryrun","n":"B2","t":"Dry run by hand: [5, 1, 4, 2, 8]"},{"id":"bs-brute","n":"B3","t":"V1 · Brute force: always n − 1 full sweeps"},{"id":"bs-standard","n":"B4","t":"V2 · Standard: shrink the inner loop"},{"id":"bs-flag","n":"B5","t":"V3 · Optimized: the swapped flag (early exit)"},{"id":"bs-last","n":"B6","t":"V4 · Last-swap boundary: shrink by many slots at once"},{"id":"bs-dowhile","n":"B7","t":"V5 · The while and do-while forms"},{"id":"bs-rec","n":"B8","t":"V6 · Recursive bubble sort"},{"id":"bs-fullrec","n":"B9","t":"V7 · Fully recursive: no loops at all"},{"id":"bs-generic","n":"B10","t":"V8 · Generic, descending, and stable bubble sort"},{"id":"bs-family","n":"B11","t":"The family: cocktail shaker, odd–even and comb sort"},{"id":"bs-special","n":"B12","t":"Special cases: linked lists, inversions, top-k and swap traps"},{"id":"bs-cost","n":"B13","t":"Time and space complexity: the master table"},{"id":"bs-review","n":"B14","t":"Bubble sort: mistakes, interview questions and review"},{"id":"sl-idea","n":"SL1","t":"Selection sort: the idea and a dry run"},{"id":"sl-types","n":"SL2","t":"Selection sort: every type in Java"},{"id":"sl-cost","n":"SL3","t":"Selection sort: time and space complexity"},{"id":"sl-review","n":"SL4","t":"Selection sort: interview problems, mistakes and questions"},{"id":"in-idea","n":"IN1","t":"Insertion sort: the idea and a dry run"},{"id":"in-types","n":"IN2","t":"Insertion sort: every type in Java"},{"id":"in-cost","n":"IN3","t":"Insertion sort: time and space complexity"},{"id":"in-review","n":"IN4","t":"Insertion sort: interview problems, mistakes and questions"},{"id":"mg-idea","n":"MG1","t":"Merge sort: the idea and a dry run"},{"id":"mg-types","n":"MG2","t":"Merge sort: every type in Java"},{"id":"mg-cost","n":"MG3","t":"Merge sort: time and space complexity"},{"id":"mg-review","n":"MG4","t":"Merge sort: interview problems, mistakes and questions"},{"id":"qk-idea","n":"QK1","t":"Quick sort: the idea and a dry run"},{"id":"qk-types","n":"QK2","t":"Quick sort: every type in Java"},{"id":"qk-cost","n":"QK3","t":"Quick sort: time and space complexity"},{"id":"qk-review","n":"QK4","t":"Quick sort: interview problems, mistakes and questions"},{"id":"hp-idea","n":"HP1","t":"Heap sort: the idea and a dry run"},{"id":"hp-types","n":"HP2","t":"Heap sort: every type in Java"},{"id":"hp-cost","n":"HP3","t":"Heap sort: time and space complexity"},{"id":"hp-review","n":"HP4","t":"Heap sort: interview problems, mistakes and questions"},{"id":"ct-idea","n":"CT1","t":"Counting sort: the idea and a dry run"},{"id":"ct-types","n":"CT2","t":"Counting sort: every type in Java"},{"id":"ct-cost","n":"CT3","t":"Counting sort: time and space complexity"},{"id":"ct-review","n":"CT4","t":"Counting sort: interview problems, mistakes and questions"},{"id":"rx-idea","n":"RX1","t":"Radix sort: the idea and a dry run"},{"id":"rx-cost","n":"RX2","t":"Radix sort: time and space complexity"},{"id":"rx-review","n":"RX3","t":"Radix sort: interview problems, mistakes and questions"},{"id":"bk-idea","n":"BK1","t":"Bucket sort: the idea and a dry run"},{"id":"bk-cost","n":"BK2","t":"Bucket sort: time and space complexity"},{"id":"bk-review","n":"BK3","t":"Bucket sort: interview problems, mistakes and questions"},{"id":"cy-idea","n":"CY1","t":"Cyclic sort: the idea and a dry run"},{"id":"cy-cost","n":"CY2","t":"Cyclic sort: time and space complexity"},{"id":"cy-review","n":"CY3","t":"Cyclic sort: interview problems, mistakes and questions"},{"id":"df-idea","n":"DF1","t":"Dutch National Flag: the idea and a dry run"},{"id":"df-cost","n":"DF2","t":"Dutch National Flag: time and space complexity"},{"id":"df-review","n":"DF3","t":"Dutch National Flag: interview problems, mistakes and questions"}]},{"key":"practice","file":"practice.html","name":"Practice","short":"Practice","band":"","sections":[{"id":"playground","n":"16","t":"Playground"},{"id":"mock","n":"17","t":"Mock interview"},{"id":"bigo","n":"18","t":"Complexity cheat sheet"},{"id":"memlab","n":"19","t":"Memory Lab"},{"id":"race","n":"20","t":"Algorithm race"},{"id":"revise","n":"21","t":"Revise"},{"id":"feedback","n":"22","t":"Your feedback"}]}],"qa":[{"k":"f-review:01","l":"L00","sec":"f-review","st":"Foundations: interview questions and review","q":"What is the difference between the JDK, JRE and JVM?","a":"JVM runs bytecode. JRE = JVM + standard libraries (enough to run). JDK = JRE + development tools such as <code>javac</code>, <code>javap</code> and <code>jshell</code>."},{"k":"f-review:02","l":"L00","sec":"f-review","st":"Foundations: interview questions and review","q":"Why is Java called platform independent?","a":"<code>javac</code> produces bytecode, not machine code. Any OS with a JVM can run the same <code>.class</code> file. The JVM itself is platform-specific."},{"k":"f-review:03","l":"L00","sec":"f-review","st":"Foundations: interview questions and review","q":"What does the JIT compiler do?","a":"It watches which methods run often and compiles them to optimised native code at run time (HotSpot: C1, then C2), so long-running Java code runs close to C speed."},{"k":"f-review:04","l":"L00","sec":"f-review","st":"Foundations: interview questions and review","q":"Name the 8 primitive types and their sizes.","a":"<code>byte</code> 8, <code>short</code> 16, <code>int</code> 32, <code>long</code> 64, <code>float</code> 32, <code>double</code> 64, <code>char</code> 16 (unsigned) bits, and <code>boolean</code> (size not specified by the language)."},{"k":"f-review:05","l":"L00","sec":"f-review","st":"Foundations: interview questions and review","q":"Why does <code>Integer a = 128, b = 128; a == b</code> print false?","a":"Autoboxing calls <code>Integer.valueOf</code>, which caches only −128..127. 128 creates two objects, and <code>==</code> compares references. Use <code>equals</code>."},{"k":"f-review:06","l":"L00","sec":"f-review","st":"Foundations: interview questions and review","q":"Do local variables get default values?","a":"No. Fields and array elements do. Reading an unassigned local is a compile error: <i>variable might not have been initialized</i>."},{"k":"f-review:07","l":"L00","sec":"f-review","st":"Foundations: interview questions and review","q":"Why does <code>byte b = 10; b += 1;</code> compile but <code>b = b + 1;</code> doesn't?","a":"<code>b + 1</code> is an <code>int</code>. Compound assignment includes an implicit cast back to the variable's type: <code>b = (byte) (b + 1)</code>."},{"k":"f-review:08","l":"L00","sec":"f-review","st":"Foundations: interview questions and review","q":"What is <code>Integer.MAX_VALUE + 1</code>?","a":"<code>Integer.MIN_VALUE</code> (−2147483648). Integer overflow wraps silently. Use <code>long</code> or <code>Math.addExact</code>."},{"k":"f-review:09","l":"L00","sec":"f-review","st":"Foundations: interview questions and review","q":"Why should you not use <code>double</code> for money?","a":"It is binary floating point, so 0.1 can't be stored exactly (<code>0.1 + 0.2</code> is <code>0.30000000000000004</code>). Use <code>BigDecimal</code> from a String, or a <code>long</code> of cents."},{"k":"f-review:10","l":"L00","sec":"f-review","st":"Foundations: interview questions and review","q":"What is the difference between a switch statement and a switch expression?","a":"The expression (Java 14+) uses <code>-&gt;</code>, never falls through, must be exhaustive and returns a value (<code>yield</code> inside a block). The classic statement falls through without <code>break</code>."},{"k":"f-review:11","l":"L00","sec":"f-review","st":"Foundations: interview questions and review","q":"How does the compiler choose between overloaded methods?","a":"In three phases: exact/widening without boxing, then boxing, then varargs; the most specific match in the first successful phase wins. It uses compile-time types."},{"k":"f-review:12","l":"L00","sec":"f-review","st":"Foundations: interview questions and review","q":"Is Java pass-by-value or pass-by-reference?","a":"Always pass-by-value. For objects the value is a reference, so the method can mutate the object but can't reassign the caller's variable. A <code>swap</code> method proves it."},{"k":"qa:01","l":"L01","sec":"qa","st":"15 interview questions","q":"What is a String? Is it a primitive?","a":"An object of the <code>final</code> class <code>java.lang.String</code>: an immutable sequence of UTF-16 chars. It is not a primitive, but the language gives it special support (literals, <code>+</code>, <code>switch</code>)."},{"k":"qa:02","l":"L01","sec":"qa","st":"15 interview questions","q":"Why is String immutable?","a":"Pool sharing is safe, checked values can't change (security), it is thread-safe with no locks, the <code>hashCode</code> can be cached for fast HashMap keys, and class loading is reliable."},{"k":"qa:03","l":"L01","sec":"qa","st":"15 interview questions","q":"What is the String pool? Where is it?","a":"A table holding one shared copy of each literal (and of each interned String). It moved from PermGen to the main heap in Java 7."},{"k":"qa:04","l":"L01","sec":"qa","st":"15 interview questions","q":"What is the difference between == and equals()?","a":"<code>==</code> compares references and <code>equals()</code> compares characters. Always use <code>equals</code> for content."},{"k":"qa:05","l":"L01","sec":"qa","st":"15 interview questions","q":"How many objects does <code>new String(\"abc\")</code> create?","a":"One or two: the pooled literal (if it isn't already there) plus one new heap object."},{"k":"qa:06","l":"L01","sec":"qa","st":"15 interview questions","q":"What does intern() do?","a":"It returns the canonical pooled copy with the same content, adding it if it is missing."},{"k":"qa:07","l":"L01","sec":"qa","st":"15 interview questions","q":"String vs StringBuilder vs StringBuffer?","a":"String is immutable. StringBuilder is mutable, not synchronized, and fastest. StringBuffer is mutable and synchronized, so it is slower."},{"k":"qa:08","l":"L01","sec":"qa","st":"15 interview questions","q":"Why is <code>+=</code> in a loop slow?","a":"Each iteration copies everything built so far, which is O(n²) in total. One StringBuilder makes it O(n)."},{"k":"qa:09","l":"L01","sec":"qa","st":"15 interview questions","q":"Why is <code>\"a\" + \"b\" == \"ab\"</code> true, but <code>a + \"b\" == \"ab\"</code> false?","a":"Literal concatenation is a compile-time constant, so it is pooled. With a non-final variable, the String is built at runtime as a new object. A <code>final</code> variable makes the result <code>true</code> again."},{"k":"qa:10","l":"L01","sec":"qa","st":"15 interview questions","q":"Why is char[] preferred over String for passwords?","a":"A String stays in memory until garbage collection and can't be wiped. A <code>char[]</code> can be overwritten right after use, and it is less likely to be logged by accident."},{"k":"qa:11","l":"L01","sec":"qa","st":"15 interview questions","q":"Can String be extended? Why is it final?","a":"No. Making it final protects immutability and security, and it allows JVM optimisations."},{"k":"qa:12","l":"L01","sec":"qa","st":"15 interview questions","q":"How does compareTo work?","a":"It returns the difference of the first pair of characters that differ. If one String is a prefix of the other, it returns the length difference. The result is 0 when the Strings are equal."},{"k":"qa:13","l":"L01","sec":"qa","st":"15 interview questions","q":"What are Compact Strings?","a":"Since Java 9, Strings store a <code>byte[]</code> plus a coder. LATIN-1 text uses 1 byte per char, which halves the character storage (the object header and fields stay the same, so \"hello\" goes from 56 to 48 bytes)."},{"k":"qa:14","l":"L01","sec":"qa","st":"15 interview questions","q":"Why does <code>\"hi😀\".length()</code> return 4?","a":"<code>length()</code> counts UTF-16 code units, and the emoji is a surrogate pair. <code>codePointCount</code> gives 3."},{"k":"qa:15","l":"L01","sec":"qa","st":"15 interview questions","q":"How does switch work with Strings?","a":"The compiler switches on <code>hashCode()</code>, then calls <code>equals()</code> to confirm. A <code>null</code> selector throws NullPointerException (unless there is a <code>case null</code>, Java 21+)."},{"k":"d-qa:01","l":"L02","sec":"d-qa","st":"25 more interview questions","q":"Where is the pool in Java 6, 7 and 8+?","a":"Java 6: PermGen (fixed size). Java 7: moved to the main heap. Java 8+: still in the heap. Metaspace replaced PermGen, but it holds class metadata, not the pool."},{"k":"d-qa:02","l":"L02","sec":"d-qa","st":"25 more interview questions","q":"Are pooled Strings ever garbage-collected?","a":"Yes. Up to Java 6 only when PermGen was collected (a full GC); since Java 7 they are ordinary heap objects. Entries are held weakly. Literals stay alive while their class is loaded."},{"k":"d-qa:03","l":"L02","sec":"d-qa","st":"25 more interview questions","q":"When exactly is a literal added to the pool?","a":"Lazily: the first time its <code>ldc</code> instruction runs."},{"k":"d-qa:04","l":"L02","sec":"d-qa","st":"25 more interview questions","q":"What changed in intern() in Java 7?","a":"Java 6 copied the String into PermGen. Java 7+ stores a reference to the existing heap object, so <code>s.intern() == s</code> can be true."},{"k":"d-qa:05","l":"L02","sec":"d-qa","st":"25 more interview questions","q":"Does <code>new String(\"abc\")</code> copy the characters?","a":"No. It shares the pooled String's <code>byte[]</code>. Only the String object is new."},{"k":"d-qa:06","l":"L02","sec":"d-qa","st":"25 more interview questions","q":"How many objects does <code>new String(\"a\") + new String(\"b\")</code> create?","a":"5 Strings: pooled \"a\" and \"b\", 2 heap copies, and \"ab\" on the heap (not pooled). Before Java 9 there was also a StringBuilder."},{"k":"d-qa:07","l":"L02","sec":"d-qa","st":"25 more interview questions","q":"Is \"ab\" pooled after a runtime <code>a + b</code>?","a":"No. It is only pooled if you call <code>intern()</code>."},{"k":"d-qa:08","l":"L02","sec":"d-qa","st":"25 more interview questions","q":"Explain the equals/hashCode contract.","a":"Equal objects must have equal hashes. Equal hashes don't imply equal objects. HashMap uses the hash to find the bucket and <code>equals</code> to confirm, so override both together."},{"k":"d-qa:09","l":"L02","sec":"d-qa","st":"25 more interview questions","q":"Why is it safe for String to cache its hashCode?","a":"The content can never change, so the hash never changes either."},{"k":"d-qa:10","l":"L02","sec":"d-qa","st":"25 more interview questions","q":"Why does hashCode use 31?","a":"It is an odd prime with good spread, and <code>31*i</code> = <code>(i&lt;&lt;5) - i</code> is cheap."},{"k":"d-qa:11","l":"L02","sec":"d-qa","st":"25 more interview questions","q":"Can two different Strings have the same hash?","a":"Yes. <code>\"Aa\"</code> and <code>\"BB\"</code> are both 2112."},{"k":"d-qa:12","l":"L02","sec":"d-qa","st":"25 more interview questions","q":"When does a String use 2 bytes per char?","a":"When any character is outside Latin-1 (Hindi, Chinese, emoji). Then the coder is UTF16 for the whole String."},{"k":"d-qa:13","l":"L02","sec":"d-qa","st":"25 more interview questions","q":"Is final the same as immutable?","a":"No. <code>final</code> stops reassignment of the variable. A <code>final StringBuilder</code> can still change."},{"k":"d-qa:14","l":"L02","sec":"d-qa","st":"25 more interview questions","q":"How is String made immutable?","a":"A final class, a <code>private final byte[]</code>, no setters, defensive copies, and new objects for every change."},{"k":"d-qa:15","l":"L02","sec":"d-qa","st":"25 more interview questions","q":"What is StringBuilder's default capacity, and how does it grow?","a":"16 (or 16 + the initial text length). When full, it grows to <code>old * 2 + 2</code>, or exactly what is needed if that is more."},{"k":"d-qa:16","l":"L02","sec":"d-qa","st":"25 more interview questions","q":"length() vs capacity()?","a":"The characters used vs the characters that fit before the buffer grows."},{"k":"d-qa:17","l":"L02","sec":"d-qa","st":"25 more interview questions","q":"Why is <code>sb1.equals(sb2)</code> false for the same text?","a":"StringBuilder doesn't override <code>equals</code>, so it compares references. Use <code>compareTo</code> (11+) or <code>toString().equals</code>."},{"k":"d-qa:18","l":"L02","sec":"d-qa","st":"25 more interview questions","q":"Is StringBuffer fully thread-safe?","a":"Each call is synchronized, but a sequence of calls (check, then append) is not atomic."},{"k":"d-qa:19","l":"L02","sec":"d-qa","st":"25 more interview questions","q":"Why was StringBuilder added in Java 5?","a":"Most building happens in one thread, so StringBuffer's locks were wasted cost. StringBuilder has the same API without them."},{"k":"d-qa:20","l":"L02","sec":"d-qa","st":"25 more interview questions","q":"How does <code>+</code> work in Java 9+?","a":"One <code>invokedynamic</code> call to <code>StringConcatFactory</code>. Constant-only expressions are still folded at compile time."},{"k":"d-qa:21","l":"L02","sec":"d-qa","st":"25 more interview questions","q":"Is <code>+</code> always slow?","a":"No. A single expression is optimised. It is only slow in loops."},{"k":"d-qa:22","l":"L02","sec":"d-qa","st":"25 more interview questions","q":"What does <code>String.valueOf(null)</code> do?","a":"It throws NullPointerException, because the <code>char[]</code> overload is chosen. <code>valueOf((Object) null)</code> returns <code>\"null\"</code>."},{"k":"d-qa:23","l":"L02","sec":"d-qa","st":"25 more interview questions","q":"concat() vs +?","a":"<code>concat</code> takes only a String, throws on null, and returns <code>this</code> for an empty argument. <code>+</code> accepts any type and turns null into <code>\"null\"</code>."},{"k":"d-qa:24","l":"L02","sec":"d-qa","st":"25 more interview questions","q":"What is CharSequence?","a":"A read-only char-sequence interface implemented by String, StringBuilder, StringBuffer and CharBuffer."},{"k":"d-qa:25","l":"L02","sec":"d-qa","st":"25 more interview questions","q":"Why use <code>Locale.ROOT</code> with toLowerCase()?","a":"The default locale can change the result. In Turkish, <code>I</code> becomes <code>ı</code>. Keys and protocols need a stable result."},{"k":"s-qa:01","l":"L03","sec":"s-qa","st":"15 more interview questions","q":"How do you reverse a String without <code>reverse()</code>?","a":"Copy it to a <code>char[]</code>, swap <code>a[i]</code> and <code>a[j]</code> while moving <code>i</code> up from 0 and <code>j</code> down from the end, then <code>new String(a)</code>. O(n) time."},{"k":"s-qa:02","l":"L03","sec":"s-qa","st":"15 more interview questions","q":"Why can reversing with a char swap break emoji?","a":"An emoji is a surrogate pair (2 chars). Swapping chars reverses the pair's order, which makes it invalid. <code>StringBuilder.reverse()</code> keeps pairs together."},{"k":"s-qa:03","l":"L03","sec":"s-qa","st":"15 more interview questions","q":"How do you check a palindrome in O(1) extra space?","a":"Two pointers from both ends, comparing as you go. No reversed copy is needed."},{"k":"s-qa:04","l":"L03","sec":"s-qa","st":"15 more interview questions","q":"How do you check two Strings are anagrams in O(n)?","a":"An <code>int[26]</code>: add for one String, subtract for the other, then every count must be 0. Sorting both works too, but it is O(n log n)."},{"k":"s-qa:05","l":"L03","sec":"s-qa","st":"15 more interview questions","q":"How do you find the first non-repeating character?","a":"Two passes: count every char, then scan the String in order and return the first with count 1. O(n)."},{"k":"s-qa:06","l":"L03","sec":"s-qa","st":"15 more interview questions","q":"What is the sliding window technique?","a":"Keep a substring <code>[left, right]</code>. Extend right each step and shrink left only when a rule breaks. Each index moves at most twice, so it is O(n)."},{"k":"s-qa:07","l":"L03","sec":"s-qa","st":"15 more interview questions","q":"Longest substring without repeating characters?","a":"A sliding window with a map from char to last index. When a char repeats inside the window, move left to one past its last index. Track the best <code>right - left + 1</code>."},{"k":"s-qa:08","l":"L03","sec":"s-qa","st":"15 more interview questions","q":"How do you group anagrams?","a":"Use the sorted letters (or a 26-count signature) as a map key, and add each word to the list for its key."},{"k":"s-qa:09","l":"L03","sec":"s-qa","st":"15 more interview questions","q":"How do you check if one String is a rotation of another?","a":"The lengths must be equal, and <code>(a + a).contains(b)</code> must be true."},{"k":"s-qa:10","l":"L03","sec":"s-qa","st":"15 more interview questions","q":"How do you check balanced brackets?","a":"A stack (<code>ArrayDeque</code>): push openers and pop on closers, checking that they match. It must be empty at the end."},{"k":"s-qa:11","l":"L03","sec":"s-qa","st":"15 more interview questions","q":"Why use <code>ArrayDeque</code> instead of <code>Stack</code>?","a":"<code>Stack</code> extends <code>Vector</code>, so every call is synchronized, and it is a legacy class. <code>ArrayDeque</code> is faster and is the recommended stack and queue."},{"k":"s-qa:12","l":"L03","sec":"s-qa","st":"15 more interview questions","q":"How do you write your own <code>parseInt</code>?","a":"Strip, read an optional sign, then <code>result = result * 10 + (c - '0')</code> for each digit. Reject non-digits, and check for overflow at each step (use a <code>long</code>, or compare with <code>Integer.MAX_VALUE / 10</code>)."},{"k":"s-qa:13","l":"L03","sec":"s-qa","st":"15 more interview questions","q":"Greedy vs lazy quantifiers?","a":"<code>.*</code> matches as much as possible, then backtracks. <code>.*?</code> matches as little as possible. On <code>&lt;b&gt;x&lt;/b&gt;</code>, <code>&lt;.*&gt;</code> matches everything, while <code>&lt;.*?&gt;</code> matches just <code>&lt;b&gt;</code>."},{"k":"s-qa:14","l":"L03","sec":"s-qa","st":"15 more interview questions","q":"Why precompile a Pattern?","a":"Compiling a regex costs time. <code>s.matches(regex)</code> compiles it on every call, while a static <code>Pattern</code> is compiled once and is thread-safe to reuse. (A <code>Matcher</code> is not thread-safe.)"},{"k":"s-qa:15","l":"L03","sec":"s-qa","st":"15 more interview questions","q":"What is the longest palindromic substring approach?","a":"Expand around each of the 2n−1 centres (each char and each gap) while both ends match. O(n²) time, O(1) space."},{"k":"a-qa:01","l":"L04","sec":"a-qa","st":"20 interview questions on arrays","q":"What is an array? Is it a primitive or an object?","a":"A fixed-size, indexed container of one element type. It is always an <b>object</b> (on the heap, can be null), even when it holds primitives."},{"k":"a-qa:02","l":"L04","sec":"a-qa","st":"20 interview questions on arrays","q":"Why do indexes start at 0?","a":"The index is an offset from the start: the address of <code>a[i]</code> is <code>base + i × size</code>, so the first element is at offset 0."},{"k":"a-qa:03","l":"L04","sec":"a-qa","st":"20 interview questions on arrays","q":"Why is array access O(1)?","a":"The elements are in one continuous block, so the position of any index is computed directly, with no walking."},{"k":"a-qa:04","l":"L04","sec":"a-qa","st":"20 interview questions on arrays","q":"What are the default values in a new array?","a":"0 for integer types, 0.0 for floating point, <code>'\\0'</code> for char, false for boolean, and null for objects."},{"k":"a-qa:05","l":"L04","sec":"a-qa","st":"20 interview questions on arrays","q":"<code>length</code> vs <code>length()</code> vs <code>size()</code>?","a":"Arrays have a final <code>length</code> field. String has a <code>length()</code> method. Collections have a <code>size()</code> method."},{"k":"a-qa:06","l":"L04","sec":"a-qa","st":"20 interview questions on arrays","q":"Can you change an array's size?","a":"No. You create a new array and copy into it (<code>Arrays.copyOf</code>). That is exactly what <code>ArrayList</code> does when it grows."},{"k":"a-qa:07","l":"L04","sec":"a-qa","st":"20 interview questions on arrays","q":"What is a jagged array?","a":"A 2D array whose rows have different lengths. It is possible because a 2D array is an array of references to separate row arrays."},{"k":"a-qa:08","l":"L04","sec":"a-qa","st":"20 interview questions on arrays","q":"Shallow vs deep copy of an array?","a":"A shallow copy is a new array holding the same element values or references, so object elements and 2D rows are shared. A deep copy also copies every nested object or row."},{"k":"a-qa:09","l":"L04","sec":"a-qa","st":"20 interview questions on arrays","q":"clone() vs Arrays.copyOf vs System.arraycopy?","a":"All are shallow. <code>clone</code> gives the same length. <code>copyOf</code> can resize. <code>arraycopy</code> copies into an existing array, can target any range, is the fastest, and handles overlapping ranges."},{"k":"a-qa:10","l":"L04","sec":"a-qa","st":"20 interview questions on arrays","q":"Why does <code>a.equals(b)</code> return false for equal contents?","a":"Arrays inherit <code>Object.equals</code>, which compares references. Use <code>Arrays.equals</code>, or <code>Arrays.deepEquals</code> for nested arrays."},{"k":"a-qa:11","l":"L04","sec":"a-qa","st":"20 interview questions on arrays","q":"Which algorithms does <code>Arrays.sort</code> use?","a":"Dual-Pivot Quicksort for primitives (fast, not stable, which doesn't matter for primitives), helped by insertion sort, run merging, a heap-sort fallback and, for large byte/short/char arrays, counting sort. TimSort for objects (stable, O(n) on sorted data)."},{"k":"a-qa:12","l":"L04","sec":"a-qa","st":"20 interview questions on arrays","q":"Why must object sorting be stable?","a":"Objects that compare equal can still be different, such as two employees of the same age. Stability keeps their earlier order, which lets you sort by several keys in turn."},{"k":"a-qa:13","l":"L04","sec":"a-qa","st":"20 interview questions on arrays","q":"What does <code>binarySearch</code> return when the key is missing?","a":"<code>-(insertionPoint) - 1</code>, which is always negative. The insertion point is where the key would go to keep the array sorted."},{"k":"a-qa:14","l":"L04","sec":"a-qa","st":"20 interview questions on arrays","q":"Is Java pass-by-reference for arrays?","a":"No. Java is always pass-by-value; the value is the reference. The method can change the elements, but reassigning the parameter doesn't affect the caller."},{"k":"a-qa:15","l":"L04","sec":"a-qa","st":"20 interview questions on arrays","q":"What is <code>ArrayStoreException</code>?","a":"Arrays are covariant, so a <code>String[]</code> can be used as an <code>Object[]</code>. Storing an Integer into it compiles, but the JVM checks the real type at run time and throws."},{"k":"a-qa:16","l":"L04","sec":"a-qa","st":"20 interview questions on arrays","q":"Why can't you write <code>new T[n]</code>?","a":"Generics are erased at run time, but an array must know its exact element type to do store checks. The workaround is <code>(T[]) new Object[n]</code>, or <code>Array.newInstance(cls, n)</code>."},{"k":"a-qa:17","l":"L04","sec":"a-qa","st":"20 interview questions on arrays","q":"What is the problem with <code>Arrays.asList</code>?","a":"It returns a fixed-size view backed by the array (no add or remove; <code>set</code> writes through). With an <code>int[]</code> it gives a list containing one element: the array itself."},{"k":"a-qa:18","l":"L04","sec":"a-qa","st":"20 interview questions on arrays","q":"Array vs ArrayList: when do you use which?","a":"An array for a fixed size, primitives, or performance-critical code. An <code>ArrayList</code> when the size changes or you need collection APIs and generics."},{"k":"a-qa:19","l":"L04","sec":"a-qa","st":"20 interview questions on arrays","q":"How do you find the maximum subarray sum?","a":"Kadane's algorithm: at each element, either extend the current sum or restart from this element, and track the best. O(n), O(1)."},{"k":"a-qa:20","l":"L04","sec":"a-qa","st":"20 interview questions on arrays","q":"How do you rotate an array by k in place?","a":"Reverse the whole array, then reverse the first k elements, then reverse the rest (use <code>k % n</code>). O(n) time, O(1) space."},{"k":"o-review:01","l":"L05","sec":"o-review","st":"OOP: interview questions and review","q":"What are the four pillars of OOP?","a":"Encapsulation (private state behind methods), inheritance (subtypes reuse and specialise a parent), polymorphism (one reference type, many implementations chosen at run time) and abstraction (depend on contracts, not implementations)."},{"k":"o-review:02","l":"L05","sec":"o-review","st":"OOP: interview questions and review","q":"What is the difference between a class and an object?","a":"A class is the blueprint loaded once into Metaspace; an object is an instance created with <code>new</code> on the heap, with its own copy of the instance fields. Variables hold references to objects."},{"k":"o-review:03","l":"L05","sec":"o-review","st":"OOP: interview questions and review","q":"What is the order of initialisation for <code>new Child()</code>?","a":"Static blocks and static fields, parent then child (once per class). Then the parent's field initialisers, instance blocks and constructor; then the child's field initialisers and instance blocks in source order, then the rest of the child's constructor."},{"k":"o-review:04","l":"L05","sec":"o-review","st":"OOP: interview questions and review","q":"Does Java give you a default constructor?","a":"Only if the class declares no constructor at all. Declare any constructor and the no-arg one disappears, so <code>new Dog()</code> stops compiling."},{"k":"o-review:05","l":"L05","sec":"o-review","st":"OOP: interview questions and review","q":"Overloading vs overriding?","a":"Overloading: same name, different parameters, chosen at compile time from declared types. Overriding: a subclass redefines an inherited instance method with the same signature (covariant return, same or wider access, no broader checked exceptions), chosen at run time from the object's class."},{"k":"o-review:06","l":"L05","sec":"o-review","st":"OOP: interview questions and review","q":"Can you override a static or a private method?","a":"No. A static method with the same signature in a subclass <i>hides</i> the parent's, and the declared type decides which runs. A private method is invisible to subclasses, so a same-named method is unrelated."},{"k":"o-review:07","l":"L05","sec":"o-review","st":"OOP: interview questions and review","q":"Are fields polymorphic?","a":"No. A field with the same name in a subclass hides the parent's; <code>Animal a = new Dog(); a.name</code> reads Animal's field. Only instance methods are dispatched dynamically."},{"k":"o-review:08","l":"L05","sec":"o-review","st":"OOP: interview questions and review","q":"Why shouldn't a constructor call an overridable method?","a":"Dispatch already uses the subclass during the parent's constructor, but the subclass fields are not initialised yet, so the override sees <code>null</code>/0. Make such methods <code>private</code> or <code>final</code>."},{"k":"o-review:09","l":"L05","sec":"o-review","st":"OOP: interview questions and review","q":"Abstract class vs interface: when do you use each?","a":"Interface for a capability or contract (many per class, no state, default methods since Java 8). Abstract class when subtypes share state, constructors or a template algorithm (one per class). Default to interfaces."},{"k":"o-review:10","l":"L05","sec":"o-review","st":"OOP: interview questions and review","q":"Why prefer composition over inheritance?","a":"Inheritance couples the subclass to the parent's implementation (fragile base class: a counting <code>HashSet</code> double-counts because <code>addAll</code> calls <code>add</code>). Composition depends only on an interface, hides unwanted methods and can be swapped at run time."},{"k":"o-review:11","l":"L05","sec":"o-review","st":"OOP: interview questions and review","q":"Why must you override hashCode when you override equals?","a":"The contract says equal objects must have equal hash codes. Hash collections pick a bucket by hash before calling <code>equals</code>, so without it <code>contains</code>/<code>get</code> miss logically equal keys."},{"k":"o-review:12","l":"L05","sec":"o-review","st":"OOP: interview questions and review","q":"How do you make a class immutable?","a":"<code>final</code> class, <code>private final</code> fields, no setters, defensive copies of mutable inputs and outputs, and \"change\" methods that return new objects. A <code>final</code> field alone only freezes the reference."},{"k":"o-review:13","l":"L05","sec":"o-review","st":"OOP: interview questions and review","q":"Static nested class vs inner class?","a":"A static nested class has no link to an outer instance. An inner class holds a hidden <code>Outer.this</code> reference, needs an outer object to be created (<code>outer.new Inner()</code>), and can keep that object alive (a leak risk)."},{"k":"o-review:14","l":"L05","sec":"o-review","st":"OOP: interview questions and review","q":"What does a record generate, and what can't it do?","a":"Private final fields, canonical constructor, accessors, <code>equals</code>, <code>hashCode</code>, <code>toString</code>. It is final, can't extend a class (it extends <code>Record</code>), can't declare extra instance fields, and is only shallowly immutable."},{"k":"o-review:15","l":"L05","sec":"o-review","st":"OOP: interview questions and review","q":"What problem do sealed classes solve?","a":"They close a hierarchy (<code>permits</code>), so the compiler knows every subtype. A pattern-matching <code>switch</code> over it can be exhaustive without <code>default</code>, and adding a subtype breaks the compile exactly where code must change."},{"k":"cx-complexity:01","l":"L06","sec":"cx-complexity","st":"Time and space complexity: from scratch to advanced","q":"What is time complexity, and why not just measure the time?","a":"It describes how the number of steps grows with the input size n. Measured time depends on the machine, JVM warm-up and load; growth rate compares algorithms independently of all that and predicts behaviour for big inputs."},{"k":"cx-complexity:02","l":"L06","sec":"cx-complexity","st":"Time and space complexity: from scratch to advanced","q":"What is the difference between Big-O, Big-Ω and Big-Θ?","a":"O is an upper bound (grows no faster than), Ω a lower bound (at least as fast), Θ a tight bound (both). Selection sort is Θ(n²); insertion sort is O(n²) and Ω(n)."},{"k":"cx-complexity:03","l":"L06","sec":"cx-complexity","st":"Time and space complexity: from scratch to advanced","q":"Why do we drop constants and lower-order terms?","a":"For large n the fastest-growing term dominates, and constants depend on the machine and implementation. 3n² + 5n and n² both grow quadratically: doubling n multiplies the work by about 4."},{"k":"cx-complexity:04","l":"L06","sec":"cx-complexity","st":"Time and space complexity: from scratch to advanced","q":"Why is binary search O(log n)?","a":"Each step halves the remaining range: n, n/2, n/4 … 1. The number of halvings until one element is left is log₂ n (about 20 for a million)."},{"k":"cx-complexity:05","l":"L06","sec":"cx-complexity","st":"Time and space complexity: from scratch to advanced","q":"What is amortized O(1) for ArrayList.add?","a":"Most adds are O(1); when the array is full it is copied into one 1.5× bigger. The copies form a geometric series, so n adds cost O(n) in total: O(1) per add on average over any sequence, with no randomness involved."},{"k":"cx-complexity:06","l":"L06","sec":"cx-complexity","st":"Time and space complexity: from scratch to advanced","q":"What is the time and space complexity of naive recursive Fibonacci?","a":"Time O(2ⁿ) (more precisely about 1.618ⁿ; fib(30) makes 2,692,537 calls). Space O(n): the stack holds only one root-to-leaf path. Memoization makes it O(n) time; a loop makes it O(n) time and O(1) space."},{"k":"cx-complexity:07","l":"L06","sec":"cx-complexity","st":"Time and space complexity: from scratch to advanced","q":"What is the complexity of merge sort, and how do you derive it?","a":"T(n) = 2T(n/2) + O(n). The recursion tree has log₂ n levels, each doing O(n) merging in total, so O(n log n). Space O(n) for the temporary array plus O(log n) stack. By the master theorem a = 2 = b^d."},{"k":"cx-complexity:08","l":"L06","sec":"cx-complexity","st":"Time and space complexity: from scratch to advanced","q":"Does recursion use extra space even if it creates no arrays?","a":"Yes: every active call is a stack frame. Space is O(maximum recursion depth): O(n) for linear recursion, O(log n) for balanced halving."},{"k":"cx-complexity:09","l":"L06","sec":"cx-complexity","st":"Time and space complexity: from scratch to advanced","q":"What does O(n + m) mean, and when is it not O(n)?","a":"Two independent inputs of sizes n and m. It is not O(n) because m can be much larger than n; e.g. checking if string t contains all letters of s is O(n + m)."},{"k":"cx-complexity:10","l":"L06","sec":"cx-complexity","st":"Time and space complexity: from scratch to advanced","q":"Why can't a comparison sort be faster than O(n log n)?","a":"There are n! possible orders and each comparison has two outcomes, so the decision tree needs height ≥ log₂(n!) ≈ n log₂ n. Counting/radix/bucket sorts avoid it by not comparing."},{"k":"cx-complexity:11","l":"L06","sec":"cx-complexity","st":"Time and space complexity: from scratch to advanced","q":"What is the complexity of building a String with += in a loop?","a":"O(n²): Strings are immutable, so each += copies the whole current string (1 + 2 + … + n chars). StringBuilder appends into a growing buffer: O(n) total."},{"k":"cx-complexity:12","l":"L06","sec":"cx-complexity","st":"Time and space complexity: from scratch to advanced","q":"Give an example of trading space for time.","a":"Two Sum: O(n²) time with O(1) space by checking all pairs, or O(n) time with a HashMap of seen values at O(n) space. Memoization and prefix sums are the same idea."},{"k":"bs-review:01","l":"L06","sec":"bs-review","st":"Bubble sort: mistakes, interview questions and review","q":"How does bubble sort work?","a":"It compares each pair of neighbours <code>a[j]</code>, <code>a[j+1]</code> and swaps them if they are out of order. One walk over the array is a pass; after pass k the k largest values are in their final places at the end. At most n − 1 passes sort the array."},{"k":"bs-review:02","l":"L06","sec":"bs-review","st":"Bubble sort: mistakes, interview questions and review","q":"What are the best, average and worst case time complexities?","a":"Worst and average O(n²). Best case O(n) only with the swapped-flag optimization (one pass over sorted input); the plain version is O(n²) even on sorted input."},{"k":"bs-review:03","l":"L06","sec":"bs-review","st":"Bubble sort: mistakes, interview questions and review","q":"What is the space complexity?","a":"O(1) extra for the loop versions: a few index variables, a temp and a flag. The recursive versions need O(n) stack frames."},{"k":"bs-review:04","l":"L06","sec":"bs-review","st":"Bubble sort: mistakes, interview questions and review","q":"Is bubble sort stable? Why?","a":"Yes: it only swaps when the left element is strictly greater, so two equal elements never pass each other. Using <code>&gt;=</code> breaks stability."},{"k":"bs-review:05","l":"L06","sec":"bs-review","st":"Bubble sort: mistakes, interview questions and review","q":"Why can the inner loop stop at <code>n − 1 − i</code>?","a":"Invariant: after pass i (from 0), the last i + 1 slots hold the largest values in their final order, so comparing them again can never cause a swap. The last pair to compare is <code>(n−2−i, n−1−i)</code>."},{"k":"bs-review:06","l":"L06","sec":"bs-review","st":"Bubble sort: mistakes, interview questions and review","q":"What does the swapped flag do, and why is it correct?","a":"It records whether a pass swapped anything. If not, every neighbour pair is in order, so the array is sorted and the loop can stop. It turns the best case into O(n)."},{"k":"bs-review:07","l":"L06","sec":"bs-review","st":"Bubble sort: mistakes, interview questions and review","q":"How many comparisons and swaps does bubble sort make on a reversed array of n elements?","a":"n(n−1)/2 comparisons and n(n−1)/2 swaps: every pair is an inversion and every comparison causes a swap. For n = 5 that is 10 and 10."},{"k":"bs-review:08","l":"L06","sec":"bs-review","st":"Bubble sort: mistakes, interview questions and review","q":"How do you write bubble sort recursively, and what does it cost?","a":"Base case <code>n ≤ 1</code>; otherwise do one pass to move the largest to index n−1, then recurse on n − 1. Time T(n) = T(n−1) + O(n) = O(n²); space O(n) for the call stack. A fully recursive version also turns the pass into recursion, still O(n) stack."},{"k":"bs-review:09","l":"L06","sec":"bs-review","st":"Bubble sort: mistakes, interview questions and review","q":"What are \"turtles\" and \"rabbits\"?","a":"Large values near the start move quickly to the end (many positions per pass): rabbits. Small values near the end move only one position left per pass: turtles. Cocktail shaker and comb sort exist to move turtles faster."},{"k":"bs-review:10","l":"L06","sec":"bs-review","st":"Bubble sort: mistakes, interview questions and review","q":"What is the relationship between swaps and inversions?","a":"Each adjacent swap of an out-of-order pair removes exactly one inversion and creates none, and bubble sort ends at 0 inversions, so the number of swaps equals the number of inversions in the input."},{"k":"bs-review:11","l":"L06","sec":"bs-review","st":"Bubble sort: mistakes, interview questions and review","q":"How is cocktail shaker sort different from bubble sort?","a":"It alternates a forward pass (largest to the end) with a backward pass (smallest to the front), shrinking from both sides. Same O(n²) worst case, but turtles move to the front in one backward pass, so it often needs fewer passes."},{"k":"bs-review:12","l":"L06","sec":"bs-review","st":"Bubble sort: mistakes, interview questions and review","q":"What is comb sort, and is it stable?","a":"Bubble sort that compares elements a gap apart, shrinking the gap by about 1.3 each pass until it reaches 1. It kills turtles early and is much faster in practice, but swaps over a distance can jump over equal elements, so it is not stable. Worst case still O(n²)."},{"k":"bs-review:13","l":"L06","sec":"bs-review","st":"Bubble sort: mistakes, interview questions and review","q":"Why is odd–even transposition sort interesting?","a":"The pairs compared in one phase never overlap, so all of them can be compared at the same time. With n/2 processors it sorts in n rounds: O(n) parallel time. It is used in sorting networks and GPUs."},{"k":"bs-review:14","l":"L06","sec":"bs-review","st":"Bubble sort: mistakes, interview questions and review","q":"How do you bubble sort a linked list?","a":"Walk with <code>cur</code> and <code>cur.next</code> up to a moving <code>end</code> marker. Either swap the values (simplest), or relink nodes using a dummy head and a <code>prev</code> pointer: <code>prev.next = nxt; cur.next = nxt.next; nxt.next = cur</code>. O(n²) time, O(1) space."},{"k":"bs-review:15","l":"L06","sec":"bs-review","st":"Bubble sort: mistakes, interview questions and review","q":"When would you actually use bubble sort?","a":"Very small inputs, data that is almost sorted, checking if an array is sorted in one pass, parallel sorting networks (odd–even), or teaching. For real data use <code>Arrays.sort</code> / <code>List.sort</code>: Dual-Pivot Quicksort for primitives, TimSort for objects."},{"k":"sl-review:01","l":"L06","sec":"sl-review","st":"Selection sort: interview problems, mistakes and questions","q":"How does selection sort work?","a":"Repeatedly find the minimum of the unsorted part and swap it to the front of that part. After pass i the first i + 1 values are final."},{"k":"sl-review:02","l":"L06","sec":"sl-review","st":"Selection sort: interview problems, mistakes and questions","q":"What is its time complexity in the best case?","a":"O(n²): it always scans the whole unsorted part to be sure it found the minimum, even on sorted input."},{"k":"sl-review:03","l":"L06","sec":"sl-review","st":"Selection sort: interview problems, mistakes and questions","q":"Why is selection sort not stable?","a":"The swap moves a[i] far to the right, possibly past an equal value. [2ᴬ, 2ᴮ, 1] becomes [1, 2ᴮ, 2ᴬ]."},{"k":"sl-review:04","l":"L06","sec":"sl-review","st":"Selection sort: interview problems, mistakes and questions","q":"When would you choose selection sort over insertion sort?","a":"When writes are much more expensive than reads: selection sort makes at most n − 1 swaps, insertion sort up to n²/2 shifts."},{"k":"sl-review:05","l":"L06","sec":"sl-review","st":"Selection sort: interview problems, mistakes and questions","q":"How many comparisons for n = 5?","a":"n(n − 1)/2 = 10, on every input (the dry run prints comparisons = 10, swaps = 3)."},{"k":"in-review:01","l":"L06","sec":"in-review","st":"Insertion sort: interview problems, mistakes and questions","q":"How does insertion sort work?","a":"It grows a sorted prefix: each new value is shifted left past bigger values until it fits, like sorting cards in your hand."},{"k":"in-review:02","l":"L06","sec":"in-review","st":"Insertion sort: interview problems, mistakes and questions","q":"What are its best and worst cases?","a":"Best O(n) on sorted input (one comparison per element); worst O(n²) on reversed input (every pair shifts)."},{"k":"in-review:03","l":"L06","sec":"in-review","st":"Insertion sort: interview problems, mistakes and questions","q":"Why is insertion sort used inside TimSort and Quicksort implementations?","a":"For small runs its tiny constant factor, no recursion and adaptivity beat the n log n algorithms. Java switches to it for runs of a few dozen elements (TimSort builds runs of at least 32 with binary insertion sort)."},{"k":"in-review:04","l":"L06","sec":"in-review","st":"Insertion sort: interview problems, mistakes and questions","q":"What does \"online\" mean, and is insertion sort online?","a":"It can sort data as it arrives, without seeing the whole input first. Yes: each new value is just inserted into the sorted prefix."},{"k":"in-review:05","l":"L06","sec":"in-review","st":"Insertion sort: interview problems, mistakes and questions","q":"What does binary insertion sort improve?","a":"Comparisons drop to O(n log n) by binary-searching the position, but the shifts are still O(n²), so the time stays O(n²)."},{"k":"mg-review:01","l":"L06","sec":"mg-review","st":"Merge sort: interview problems, mistakes and questions","q":"Explain merge sort and its complexity.","a":"Split in half, sort each half recursively, merge the sorted halves with two pointers. T(n) = 2T(n/2) + n = O(n log n) in every case, O(n) extra space, stable."},{"k":"mg-review:02","l":"L06","sec":"mg-review","st":"Merge sort: interview problems, mistakes and questions","q":"Why is merge sort preferred for linked lists?","a":"It only needs sequential access: splitting uses slow/fast pointers and merging just relinks nodes, so no extra array is needed. Quicksort and heap sort need random access."},{"k":"mg-review:03","l":"L06","sec":"mg-review","st":"Merge sort: interview problems, mistakes and questions","q":"How do you count inversions with merge sort?","a":"When the merge takes tmp[j] from the right half, all mid − i + 1 values still waiting in the left half are bigger and come earlier: add that to the count. O(n log n)."},{"k":"mg-review:04","l":"L06","sec":"mg-review","st":"Merge sort: interview problems, mistakes and questions","q":"What is the difference between top-down and bottom-up merge sort?","a":"Top-down recurses on halves; bottom-up merges runs of width 1, 2, 4 … iteratively with no recursion. Same O(n log n)."},{"k":"mg-review:05","l":"L06","sec":"mg-review","st":"Merge sort: interview problems, mistakes and questions","q":"Why does Java use merge sort (TimSort) for objects but quicksort for primitives?","a":"Objects need a stable sort (equal keys keep their order) and comparisons are expensive; for primitives stability is invisible and Dual-Pivot Quicksort is faster with no extra memory."},{"k":"qk-review:01","l":"L06","sec":"qk-review","st":"Quick sort: interview problems, mistakes and questions","q":"Explain quicksort and its complexity.","a":"Choose a pivot, partition so smaller values go left and larger right (pivot is final), recurse on both sides. Average O(n log n), worst O(n²), O(log n) stack, in-place, not stable."},{"k":"qk-review:02","l":"L06","sec":"qk-review","st":"Quick sort: interview problems, mistakes and questions","q":"When does quicksort hit O(n²), and how do you avoid it?","a":"When every pivot is the smallest or largest value, e.g. sorted input with a first/last pivot, or all-equal values with a 2-way partition. Use a random pivot or median-of-three, and a 3-way partition for duplicates."},{"k":"qk-review:03","l":"L06","sec":"qk-review","st":"Quick sort: interview problems, mistakes and questions","q":"Lomuto vs Hoare partition?","a":"Lomuto: one pointer, pivot = last, simple, pivot ends at its final index. Hoare: two pointers moving inward, about three times fewer swaps, but the pivot is not necessarily at the returned index."},{"k":"qk-review:04","l":"L06","sec":"qk-review","st":"Quick sort: interview problems, mistakes and questions","q":"What is Quickselect and its complexity?","a":"Partition, then continue only into the side containing index k. Average O(n) (n + n/2 + …), worst O(n²); used for k-th largest (LC 215)."},{"k":"qk-review:05","l":"L06","sec":"qk-review","st":"Quick sort: interview problems, mistakes and questions","q":"Why is quicksort usually faster than merge sort in practice?","a":"It works in place with sequential memory access (cache-friendly) and has a small constant factor; merge sort copies into a temporary array."},{"k":"hp-review:01","l":"L06","sec":"hp-review","st":"Heap sort: interview problems, mistakes and questions","q":"Explain heap sort.","a":"Build a max-heap in place in O(n), then n − 1 times swap the root (the max) to the end and sift the new root down in O(log n). O(n log n) always, O(1) space, not stable."},{"k":"hp-review:02","l":"L06","sec":"hp-review","st":"Heap sort: interview problems, mistakes and questions","q":"Why is building a heap O(n) and not O(n log n)?","a":"Sift-down cost is the node's height. Half the nodes are leaves (0), a quarter have height 1, … The sum n/4·1 + n/8·2 + … is bounded by n."},{"k":"hp-review:03","l":"L06","sec":"hp-review","st":"Heap sort: interview problems, mistakes and questions","q":"Heap sort vs quicksort vs merge sort?","a":"Heap: O(n log n) worst, O(1) space, not stable, poor cache use. Quick: fastest on average, O(n²) worst. Merge: O(n log n) worst, stable, O(n) space."},{"k":"hp-review:04","l":"L06","sec":"hp-review","st":"Heap sort: interview problems, mistakes and questions","q":"How do you find the k-th largest with a heap?","a":"Keep a min-heap of the k largest seen so far; when it grows past k, poll the smallest. The root is the answer: O(n log k) time, O(k) space."},{"k":"hp-review:05","l":"L06","sec":"hp-review","st":"Heap sort: interview problems, mistakes and questions","q":"What are the index formulas of a binary heap stored in an array?","a":"0-based: left = 2i + 1, right = 2i + 2, parent = (i − 1) / 2; the last non-leaf is n/2 − 1."},{"k":"ct-review:01","l":"L06","sec":"ct-review","st":"Counting sort: interview problems, mistakes and questions","q":"How can counting sort beat O(n log n)?","a":"It never compares elements; it uses the values as array indexes. The Ω(n log n) lower bound only applies to comparison sorts."},{"k":"ct-review:02","l":"L06","sec":"ct-review","st":"Counting sort: interview problems, mistakes and questions","q":"What is its complexity?","a":"O(n + k) time, O(k) extra space (O(n + k) for the stable version), where k is the range of values."},{"k":"ct-review:03","l":"L06","sec":"ct-review","st":"Counting sort: interview problems, mistakes and questions","q":"How do you make counting sort stable?","a":"Turn counts into prefix sums (positions), then place elements from the right end of the input at out[--count[x]]."},{"k":"ct-review:04","l":"L06","sec":"ct-review","st":"Counting sort: interview problems, mistakes and questions","q":"When is counting sort a bad idea?","a":"When the range k is much larger than n (sparse wide values), or keys are not small integers."},{"k":"ct-review:05","l":"L06","sec":"ct-review","st":"Counting sort: interview problems, mistakes and questions","q":"Where does counting sort appear in String problems?","a":"Every <code>int[26]</code> or <code>int[128]</code> frequency array: anagrams, first unique character, sort by frequency."},{"k":"rx-review:01","l":"L06","sec":"rx-review","st":"Radix sort: interview problems, mistakes and questions","q":"How does LSD radix sort work?","a":"Stable counting sort by the ones digit, then the tens, and so on up to the most significant digit. Stability keeps the earlier digits' order inside equal digits."},{"k":"rx-review:02","l":"L06","sec":"rx-review","st":"Radix sort: interview problems, mistakes and questions","q":"What is its complexity?","a":"O(d·(n + b)) time and O(n + b) space, where d is the number of digits and b the base."},{"k":"rx-review:03","l":"L06","sec":"rx-review","st":"Radix sort: interview problems, mistakes and questions","q":"Why must each pass be stable?","a":"Pass k must keep the order created by passes 1 … k − 1 among values with the same k-th digit; otherwise the lower digits are scrambled."},{"k":"rx-review:04","l":"L06","sec":"rx-review","st":"Radix sort: interview problems, mistakes and questions","q":"Radix sort vs counting sort?","a":"Counting sort needs the whole range k in memory; radix sort handles big ranges by counting one digit (base b) at a time."},{"k":"bk-review:01","l":"L06","sec":"bk-review","st":"Bucket sort: interview problems, mistakes and questions","q":"How does bucket sort work and when is it linear?","a":"Scatter values into range buckets, sort each bucket, concatenate. It is O(n + k) on average when values are spread uniformly so each bucket is small."},{"k":"bk-review:02","l":"L06","sec":"bk-review","st":"Bucket sort: interview problems, mistakes and questions","q":"What is its worst case?","a":"All values in one bucket: the cost of the inner sort on n values, O(n²) with insertion sort."},{"k":"bk-review:03","l":"L06","sec":"bk-review","st":"Bucket sort: interview problems, mistakes and questions","q":"How does bucket sort solve Top K Frequent in O(n)?","a":"Frequencies are between 1 and n, so use them as bucket indexes: bucket[f] lists values seen f times; collect from the highest bucket down until you have k."},{"k":"bk-review:04","l":"L06","sec":"bk-review","st":"Bucket sort: interview problems, mistakes and questions","q":"Bucket sort vs counting sort?","a":"Counting sort has one bucket per possible value (just a count); bucket sort groups a range of values per bucket and sorts inside each."},{"k":"cy-review:01","l":"L06","sec":"cy-review","st":"Cyclic sort: interview problems, mistakes and questions","q":"What is cyclic sort and when can you use it?","a":"For values in 1..n, swap each value to index v − 1 until everything is home. Only when values map to indexes; O(n) time, O(1) space."},{"k":"cy-review:02","l":"L06","sec":"cy-review","st":"Cyclic sort: interview problems, mistakes and questions","q":"Why is it O(n) even though it has a while loop with swaps?","a":"Each swap places one value permanently, so there are at most n − 1 swaps, plus n increments of i."},{"k":"cy-review:03","l":"L06","sec":"cy-review","st":"Cyclic sort: interview problems, mistakes and questions","q":"How do you find all duplicates and missing numbers with it?","a":"After the sort, every index i with a[i] ≠ i + 1 holds a duplicate a[i], and i + 1 is missing."},{"k":"cy-review:04","l":"L06","sec":"cy-review","st":"Cyclic sort: interview problems, mistakes and questions","q":"How does it find the first missing positive (LC 41)?","a":"Place every value in 1..n at its index, ignore others; the first index i with a[i] ≠ i + 1 gives the answer i + 1 (or n + 1)."},{"k":"df-review:01","l":"L06","sec":"df-review","st":"Dutch National Flag: interview problems, mistakes and questions","q":"Explain the Dutch National Flag algorithm.","a":"Three pointers lo, mid, hi keep zones [0s | 1s | unknown | 2s]. Look at a[mid]: 0 → swap to lo, lo++, mid++; 2 → swap to hi, hi--; 1 → mid++. One pass, O(1) space."},{"k":"df-review:02","l":"L06","sec":"df-review","st":"Dutch National Flag: interview problems, mistakes and questions","q":"Why don't we increment mid after swapping with hi?","a":"The value moved from hi into mid has not been examined yet; it could be a 0 or 2."},{"k":"df-review:03","l":"L06","sec":"df-review","st":"Dutch National Flag: interview problems, mistakes and questions","q":"How is it related to quicksort?","a":"It is the 3-way partition: with a pivot instead of 1, zones become &lt; pivot, = pivot, &gt; pivot, which makes quicksort fast on many duplicates."},{"k":"df-review:04","l":"L06","sec":"df-review","st":"Dutch National Flag: interview problems, mistakes and questions","q":"What is its complexity?","a":"O(n) time with at most n swaps, O(1) extra space."}]};
